# B1 - Environment & Nature (251-300)
{"german_text": "Wir sollten mehr auf die Umwelt achten.", "english_translation": "We should pay more attention to the environment.", "arabic_translation": "ينبغي أن نهتم أكثر بالبيئة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Luftverschmutzung ist ein großes Problem.", "english_translation": "Air pollution is a big problem.", "arabic_translation": "تلوث الهواء مشكلة كبيرة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich recyceln mein Papier und Plastik.", "english_translation": "I recycle my paper and plastic.", "arabic_translation": "أعيد تدوير الورق والبلاستيك الخاص بي.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Es ist wichtig, Wasser zu sparen.", "english_translation": "It's important to save water.", "arabic_translation": "من المهم توفير الماء.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Der Klimawandel betrifft uns alle.", "english_translation": "Climate change affects us all.", "arabic_translation": "تغير المناخ يؤثر علينا جميعًا.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich fahre mit dem Fahrrad zur Arbeit.", "english_translation": "I ride a bicycle to work.", "arabic_translation": "أركب الدراجة إلى العمل.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Temperaturen steigen jedes Jahr.", "english_translation": "The temperatures rise every year.", "arabic_translation": "ترتفع درجات الحرارة كل عام.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich kaufe nur noch regionale Produkte.", "english_translation": "I only buy regional products now.", "arabic_translation": "لا أشتري إلا المنتجات الإقليمية الآن.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Bäume im Park sind sehr alt.", "english_translation": "The trees in the park are very old.", "arabic_translation": "الأشجار في الحديقة قديمة جدًا.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Wir haben einen Garten angelegt.", "english_translation": "We created a garden.", "arabic_translation": "أنشأنا حديقة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Sonne scheint den ganzen Tag.", "english_translation": "The sun shines all day.", "arabic_translation": "تشرق الشمس طوال اليوم.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich habe Sonnenblumen gepflanzt.", "english_translation": "I planted sunflowers.", "arabic_translation": "زرعت دوار الشمس.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Der Sturm hat viele Äste heruntergeweht.", "english_translation": "The storm blew down many branches.", "arabic_translation": "أسقطت العاصفة العديد من الأغصان.", "level": "B1", "difficulty_score": 6, "category": "Environment"},
{"german_text": "Wir sollten weniger Plastik verwenden.", "english_translation": "We should use less plastic.", "arabic_translation": "ينبغي أن نستخدم بلاستيكًا أقل.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Das Wasser im See ist sehr klar.", "english_translation": "The water in the lake is very clear.", "arabic_translation": "الماء في البحيرة صافٍ جدًا.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich beobachte gerne Vögel.", "english_translation": "I like to watch birds.", "arabic_translation": "أحب مراقبة الطيور.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Landschaft hier ist wunderschön.", "english_translation": "The landscape here is beautiful.", "arabic_translation": "المناظر الطبيعية هنا جميلة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Wir haben an einem Baum gepflanzt.", "english_translation": "We planted a tree.", "arabic_translation": "زرعنا شجرة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Luft ist heute sehr frisch.", "english_translation": "The air is very fresh today.", "arabic_translation": "الهواء منعش جدًا اليوم.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich vermeide es, mit dem Auto zu fahren.", "english_translation": "I avoid driving a car.", "arabic_translation": "أتجنب القيادة بالسيارة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Der Wald ist ein wichtiger Lebensraum.", "english_translation": "The forest is an important habitat.", "arabic_translation": "الغابة موطن مهم.", "level": "B1", "difficulty_score": 6, "category": "Environment"},
{"german_text": "Die Blumen blühen im Frühling.", "english_translation": "The flowers bloom in spring.", "arabic_translation": "تزهر الأزهار في الربيع.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich sammle Regenwasser für meine Pflanzen.", "english_translation": "I collect rainwater for my plants.", "arabic_translation": "أجمع ماء المطر لنباتي.", "level": "B1", "difficulty_score": 6, "category": "Environment"},
{"german_text": "Die Natur gibt mir Ruhe und Entspannung.", "english_translation": "Nature gives me peace and relaxation.", "arabic_translation": "الطبيعة تمنحني السلام والاسترخاء.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich gehe gerne wandern.", "english_translation": "I like to go hiking.", "arabic_translation": "أحب الذهاب للتنزه.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Berge sind mit Schnee bedeckt.", "english_translation": "The mountains are covered with snow.", "arabic_translation": "الجبال مغطاة بالثلوج.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich habe ein Insektenhotel gebaut.", "english_translation": "I built an insect hotel.", "arabic_translation": "بنيت فندقًا للحشرات.", "level": "B1", "difficulty_score": 6, "category": "Environment"},
{"german_text": "Der Fluss ist sehr verschmutzt.", "english_translation": "The river is very polluted.", "arabic_translation": "النهر ملوث جدًا.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Ich kaufe keine Produkte, dieTierversuche beinhalten.", "english_translation": "I don't buy products that involve animal testing.", "arabic_translation": "لا أشتري منتجات تتضمن تجارب على الحيوانات.", "level": "B1", "difficulty_score": 7, "category": "Environment"},
{"german_text": "Wir haben saubere Energie installiert.", "english_translation": "We installed clean energy.", "arabic_translation": "ركبنا طاقة نظيفة.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
{"german_text": "Die Biodiversität ist bedroht.", "english_translation": "Biodiversity is threatened.", "arabic_translation": "التنوع البيولوجي مهدد.", "level": "B1", "difficulty_score": 6, "category": "Environment"},
{"german_text": "Ich habe Solarpaneele auf meinem Dach.", "english_translation": "I have solar panels on my roof.", "arabic_translation": "لدي ألواح شمسية على سطح منزلي.", "level": "B1", "difficulty_score": 6, "category": "Environment"},
{"german_text": "Das Wetter ist unberechenbar.", "english_translation": "The weather is unpredictable.", "arabic_translation": "الطقس لا يمكن التنبؤ به.", "level": "B1", "difficulty_score": 5, "category": "Environment"},
